// Shared SEO helpers: canonical URLs, page metadata and structured data.
import { dcVals } from "@/components/site/dc";

export const SITE_URL = "https://www.applotie.com";

export const BUSINESS = {
  name: "Applotie Technologies",
  phone: "+91-7250204488",
  email: "hello@applotie.com",
  city: "Patna",
  region: "Bihar",
  country: "IN",
  sameAs: ["https://in.linkedin.com/company/applotie", "https://www.instagram.com/applotie"],
};

/** Default share image, generated by app/opengraph-image.tsx. */
export const DEFAULT_OG_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "Applotie Technologies: web development and digital marketing in Patna",
};

/**
 * Build Next.js metadata for a page.
 * A page-level `openGraph` replaces the layout one entirely, so the share image is set here explicitly.
 * @param {{ title: string, description: string, path: string, robots?: import("next").Metadata["robots"] }} options
 */
export function pageMeta({ title, description, path, robots }) {
  return {
    title: { absolute: title },
    description,
    alternates: { canonical: path },
    ...(robots ? { robots } : {}),
    openGraph: {
      title,
      description,
      url: path,
      type: "website",
      siteName: BUSINESS.name,
      locale: "en_IN",
      images: [DEFAULT_OG_IMAGE],
    },
    twitter: { card: "summary_large_image", title, description, images: [DEFAULT_OG_IMAGE.url] },
  };
}

export function organizationLd() {
  return {
    "@context": "https://schema.org",
    "@type": ["LocalBusiness", "ProfessionalService"],
    "@id": `${SITE_URL}/#business`,
    name: BUSINESS.name,
    url: SITE_URL,
    logo: `${SITE_URL}/brand/applotie-lockup.svg`,
    telephone: BUSINESS.phone,
    email: BUSINESS.email,
    address: {
      "@type": "PostalAddress",
      addressLocality: BUSINESS.city,
      addressRegion: BUSINESS.region,
      addressCountry: BUSINESS.country,
    },
    areaServed: [
      { "@type": "City", name: "Patna" },
      { "@type": "State", name: "Bihar" },
    ],
    sameAs: BUSINESS.sameAs,
  };
}

export function websiteLd() {
  return {
    "@context": "https://schema.org",
    "@type": "WebSite",
    "@id": `${SITE_URL}/#website`,
    name: "Applotie",
    alternateName: BUSINESS.name,
    url: SITE_URL,
    inLanguage: "en-IN",
    publisher: { "@id": `${SITE_URL}/#business` },
  };
}

export function serviceLd({ name, description, path }) {
  return {
    "@context": "https://schema.org",
    "@type": "Service",
    name,
    description,
    url: `${SITE_URL}${path}`,
    provider: { "@id": `${SITE_URL}/#business` },
    areaServed: { "@type": "City", name: "Patna" },
  };
}

/** FAQPage structured data from a page logic class that exposes `faqs: [{ q, a }]`. */
export function faqLd(Logic) {
  const { faqs } = dcVals(Logic);
  if (!faqs || !faqs.length) return null;
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: faqs.map((f) => ({ "@type": "Question", name: f.q, acceptedAnswer: { "@type": "Answer", text: f.a } })),
  };
}

export function breadcrumbLd(items) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: items.map((it, i) => ({
      "@type": "ListItem",
      position: i + 1,
      name: it.name,
      item: `${SITE_URL}${it.path}`,
    })),
  };
}
